(() => {
  // Get all page sources in the window
  const sources = [];

  // Main page
  sources.push({url: location.href, html: document.documentElement.outerHTML});

  // Check for iframes
  const iframes = Array.from(document.querySelectorAll('iframe'));
  iframes.forEach((f, i) => {
    try {
      sources.push({url: f.src || 'iframe-' + i, html: f.contentDocument.documentElement.outerHTML});
    } catch(e) {}
  });

  // Search for all URLs in all sources
  const allUrls = new Set();
  const apiPatterns = [/supabase\.co/g, /wesbank/gi, /flickswitch/gi, /openstreetmap/gi, /tile\.openstreetmap/gi, /googleapis/gi, /gstatic/gi, /cdnjs/gi, /jsdelivr/gi, /cloudflare/gi];

  sources.forEach(src => {
    apiPatterns.forEach(p => {
      let m;
      while ((m = p.exec(src.html)) !== null) {
        allUrls.add(m[0]);
      }
    });
  });

  return JSON.stringify({
    urls: Array.from(allUrls).sort(),
    iframeCount: iframes.length
  });
})()
